async function onMountedFn(ctx) {
  const { currentRoute } = ctx.$globalVars.$router;
  if (currentRoute.query.id || currentRoute.query.orgId) {
    try {
      const result = await ctx.$requestFns.getReceives(currentRoute.query);
      let filter = [];
      const rawFilterItems = Array.isArray(currentRoute.query.filterItems) ? currentRoute.query.filterItems[0] : currentRoute.query.filterItems;
 console.log('rawFilterItems===',rawFilterItems);     if (typeof rawFilterItems === 'string' && rawFilterItems) {
        try {
          const parsedFilterItems = JSON.parse(rawFilterItems);
          filter = Array.isArray(parsedFilterItems) ? parsedFilterItems : [];
        } catch (parseError) {
          filter = [];
        }
      }
      const filterBtn = ctx.getNode('FilterSummary::filter-summary-button');
      if (filterBtn) {
        filterBtn.updateProps({ filterItems: filter });
      }
      ctx.$dataModels.formModel.qReceive = result.data.receive;
      ctx.$dataModels.detailData.oriTable = result.data.receiveMaterials;
      const tb = ctx.getNode('YqTableReport::view-material-table');
      if (tb) {
        tb.exposed.setData(ctx.$dataModels.detailData.oriTable);
      }
    } catch (err) {
      ctx.$vueGlobal.$message.error('加载单据详情失败');
      console.error('加载详情报错：', err);
    }
  } else {
    ctx.$vueGlobal.$message.error('缺少台账详情参数');
  }
}

