function(ctx) { try {
      // 筛选逻辑
      const appliedDetailQuery = ctx.$dataModels.receiveFilter.singleTable || {};
      const filterRows = ctx.$dataModels.detailData.oriTable.filter(row =>
        (!appliedDetailQuery.materialName || String(row.materialName || "").includes(appliedDetailQuery.materialName))
        && (!appliedDetailQuery.materialModel || String(row.materialModel || "").includes(appliedDetailQuery.materialModel))
        && (!appliedDetailQuery.materialCode || String(row.materialCode || "").includes(appliedDetailQuery.materialCode))
      );

      const tb = ctx.getNode('YqTableReport::view-material-table');
      if (tb) {
        tb.exposed.setData(filterRows);
      }
    } catch (err) {
      ctx.$vueGlobal.$message.error('加载单据详情失败');
      console.error('加载详情报错：', err);
    }
}

