  };
  const mappings = [{"nodeId":"RawHtml::StatBlock-raw-html-receive","label":"收料净量","field":"receiveQuantity","suffix":""},{"nodeId":"RawHtml::StatBlock-raw-html-positive","label":"正向收料量","field":"positiveQuantity","suffix":""},{"nodeId":"RawHtml::StatBlock-raw-html-return","label":"退料/冲红量","field":"returnQuantity","suffix":""},{"nodeId":"RawHtml::StatBlock-raw-html-order","label":"单据数量","field":"orderCount","suffix":"单"},{"nodeId":"RawHtml::StatBlock-raw-html-material","label":"物资种类","field":"materialCount","suffix":"种"},{"nodeId":"RawHtml::StatBlock-raw-html-supplier","label":"供应单位","field":"supplierCount","suffix":"家"}];
  mappings.forEach(function(item) {
