listRefreshCharts.fn:
async function(ctx) {
  const response = await ctx.$requestFns.loadCharts({});
  const result = response?.data || {};
  const trendChart = ctx.getNode('Chart::list-month-chart');
  const categoryChart = ctx.getNode('Chart::list-category-chart');
  const trendData = Array.isArray(result?.trend)
    ? result.trend.map(function(item) {
        return {
          name: item?.name || '',
          value: Number(item?.value || 0),
        };
      })
    : [];
  const materialData = Array.isArray(result?.materials)
    ? result.materials.map(function(item) {
        return {
          name: item?.name || '',
          materialName: item?.materialName || '',
          materialModel: item?.materialModel || '',
          materialUnit: item?.materialUnit || '',
          value: Number(item?.value || 0),
        };
      })
    : [];
  if (trendChart?.exposed?.loadData) {
   trendChart.exposed.reRender();  trendChart.exposed.loadData(trendData);
  }
  if (categoryChart?.exposed?.loadData) {
   categoryChart.exposed.reRender(); categoryChart.exposed.loadData(materialData);
  }
}
